(function(root){'use strict';
const agents={original:{name:'Kein fester Agent · Originalquellen'},'usfans.com':{name:'USFans'},'litbuy.com':{name:'Litbuy'},'pikobuy.com':{name:'Pikobuy'},'kakobuy.com':{name:'Kakobuy'},'cnfans.com':{name:'CNFans'},'mulebuy.com':{name:'Mulebuy'},'hipobuy.com':{name:'Hipobuy'},'joyagoo.com':{name:'Joyagoo'},'oopbuy.com':{name:'Oopbuy'},'gtbuy.com':{name:'Gtbuy'},'ossbuy.com':{name:'Ossbuy'}};
function ref(url){const id=root.FindsModel.identity(url).match(/^(weidian|taobao|1688):(\d+)$/);return id?{platform:id[1],id:id[2]}:null}
function raw(r){return r.platform==='weidian'?'https://weidian.com/item.html?itemID='+r.id:r.platform==='taobao'?'https://item.taobao.com/item.htm?id='+r.id:'https://detail.1688.com/offer/'+r.id+'.html'}
function convert(url,target){const r=ref(url);if(!r||!agents[target]||target==='original')return '';const base=raw(r),platform=r.platform==='1688'?'ali_1688':r.platform.toUpperCase();if(target==='usfans.com')return 'https://www.usfans.com/product/'+({weidian:3,taobao:2,'1688':1}[r.platform])+'/'+r.id;if(['litbuy.com','hipobuy.com','oopbuy.com','gtbuy.com'].includes(target))return 'https://'+target+'/product/'+r.platform+'/'+r.id;if(target==='pikobuy.com')return 'https://www.pikobuy.com/product/detail?'+new URLSearchParams({productUrl:base});if(target==='kakobuy.com')return 'https://www.kakobuy.com/item/details?'+new URLSearchParams({url:base});if(['cnfans.com','mulebuy.com','joyagoo.com'].includes(target))return 'https://'+target+'/product?'+new URLSearchParams({id:r.id,platform});if(target==='ossbuy.com')return 'https://ossbuy.com/product-detail?'+new URLSearchParams({url:base});return ''}
function preferred(g,target){if(target==='original'||!agents[target])return null;const actual=g.offers.filter(o=>root.FindsModel.shop(o)===target).sort((a,b)=>(a.euro??Infinity)-(b.euro??Infinity));if(actual.length)return {...actual[0],converted:false};const source=g.offers.find(o=>ref(o.url));if(!source)return null;const url=convert(source.url,target);if(!url)return null;return {...source,url,originalUrl:url,originUrl:source.url,shop:target,euro:null,amount:null,currency:null,raw:'Link umgewandelt · Preis bei '+agents[target].name+' noch offen',converted:true}}
const api={agents,ref,raw,convert,preferred};root.FindsAgents=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
